values
  ('05150c8e-eb0c-4453-8c8f-c77bfc703d7d', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', null, 'topic'::public.curated_course_node_type, 'Internal forces and stress', 'This module establishes internal forces and stress as the course''s first working framework. It supplies the language and representations needed before the path advances to strain and material response.', 0),
  ('c2c96db7-34d8-42a0-8f0e-b3ebc59b67c3', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '05150c8e-eb0c-4453-8c8f-c77bfc703d7d', 'subtopic'::public.curated_course_node_type, 'Section cuts', 'Section cuts identifies a specific object, distinction, or relationship within internal forces and stress. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before axial force because that next topic assumes this starting point.', 0),
  ('12047bbc-8cd9-46de-979b-edc9bbf9d59a', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '05150c8e-eb0c-4453-8c8f-c77bfc703d7d', 'subtopic'::public.curated_course_node_type, 'Axial force', 'Axial force is a governing quantity in internal forces and stress, linking local calculations to system-level behavior and offering a consistency check. After section cuts, axial force supplies what is needed to address shear.', 1),
  ('376a04ef-638e-4feb-bb69-43be2263a943', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '05150c8e-eb0c-4453-8c8f-c77bfc703d7d', 'subtopic'::public.curated_course_node_type, 'Shear', 'Shear identifies a specific object, distinction, or relationship within internal forces and stress. Learners need to recognize and use it before combining this module''s ideas in later work. After axial force, shear supplies what is needed to address moment.', 2),
  ('c2b7f561-7e73-4999-9952-1f5e460a8d99', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '05150c8e-eb0c-4453-8c8f-c77bfc703d7d', 'subtopic'::public.curated_course_node_type, 'Moment', 'Moment identifies a specific object, distinction, or relationship within internal forces and stress. Learners need to recognize and use it before combining this module''s ideas in later work. After shear, moment supplies what is needed to address stress components.', 3),
  ('5109a647-aec1-4004-8599-25a8b8fe3855', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '05150c8e-eb0c-4453-8c8f-c77bfc703d7d', 'subtopic'::public.curated_course_node_type, 'Stress components', 'Stress components is a governing quantity in internal forces and stress, linking local calculations to system-level behavior and offering a consistency check. As the final topic in this module, stress components carries the completed idea into strain and material response.', 4),
  ('45db3e2a-bf83-431e-8acf-ea18f205ebd1', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', null, 'topic'::public.curated_course_node_type, 'Strain and material response', 'This module builds directly on internal forces and stress and develops strain and material response. It belongs here because its methods and distinctions are prerequisites for axial members.', 1),
  ('9cb34447-a3ba-473b-a385-94e2c160fddb', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '45db3e2a-bf83-431e-8acf-ea18f205ebd1', 'subtopic'::public.curated_course_node_type, 'Normal/shear strain', 'Normal/shear strain is a governing quantity in strain and material response, linking local calculations to system-level behavior and offering a consistency check. It appears before hooke’s law because that next topic assumes this starting point.', 0),
  ('6f81e394-7bb8-4057-bfff-d6eec5a6629c', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '45db3e2a-bf83-431e-8acf-ea18f205ebd1', 'subtopic'::public.curated_course_node_type, 'Hooke’s law', 'Hooke’s law provides a formal guarantee or inference rule for strain and material response, allowing later conclusions to be justified rather than inferred from examples alone. After normal/shear strain, hooke’s law supplies what is needed to address poisson effect.', 1),
  ('832cdd09-d3db-4a07-a18a-80f89d93c4a5', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '45db3e2a-bf83-431e-8acf-ea18f205ebd1', 'subtopic'::public.curated_course_node_type, 'Poisson effect', 'Poisson effect identifies a specific object, distinction, or relationship within strain and material response. Learners need to recognize and use it before combining this module''s ideas in later work. After hooke’s law, poisson effect supplies what is needed to address testing.', 2),
  ('d64d28cc-ab92-472e-abbf-35dedd8704e0', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '45db3e2a-bf83-431e-8acf-ea18f205ebd1', 'subtopic'::public.curated_course_node_type, 'Testing', 'Testing connects strain and material response to observable evidence and defines what a valid measurement or interpretation must support. As the final topic in this module, testing carries the completed idea into axial members.', 3),
  ('f1bebdd4-c672-4d6b-a23b-8ae5ba722cfc', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', null, 'topic'::public.curated_course_node_type, 'Axial members', 'This module builds directly on strain and material response and develops axial members. It belongs here because its methods and distinctions are prerequisites for torsion.', 2),
  ('dabbabf3-50e4-4b33-89e4-ce8cb059e626', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', 'f1bebdd4-c672-4d6b-a23b-8ae5ba722cfc', 'subtopic'::public.curated_course_node_type, 'Deformation', 'Deformation identifies a specific object, distinction, or relationship within axial members. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before thermal strain because that next topic assumes this starting point.', 0),
  ('331325b8-4c17-4101-b268-3446e43c4670', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', 'f1bebdd4-c672-4d6b-a23b-8ae5ba722cfc', 'subtopic'::public.curated_course_node_type, 'Thermal strain', 'Thermal strain is a governing quantity in axial members, linking local calculations to system-level behavior and offering a consistency check. After deformation, thermal strain supplies what is needed to address statically indeterminate bars.', 1),
  ('f711af3d-33e2-49d5-8d29-19de71c38fc8', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', 'f1bebdd4-c672-4d6b-a23b-8ae5ba722cfc', 'subtopic'::public.curated_course_node_type, 'Statically indeterminate bars', 'Statically indeterminate bars identifies a specific object, distinction, or relationship within axial members. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, statically indeterminate bars carries the completed idea into torsion.', 2),
  ('670ce126-5111-41b5-9164-760fb9d72dd6', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', null, 'topic'::public.curated_course_node_type, 'Torsion', 'This module builds directly on axial members and develops torsion. It belongs here because its methods and distinctions are prerequisites for beam shear and moment.', 3),
  ('de5e2fca-ffa2-43bc-a04f-4b2af1795a45', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '670ce126-5111-41b5-9164-760fb9d72dd6', 'subtopic'::public.curated_course_node_type, 'Circular shafts', 'Circular shafts identifies a specific object, distinction, or relationship within torsion. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before angle of twist because that next topic assumes this starting point.', 0),
  ('980e674e-c745-441c-a0f0-ae72f413717b', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '670ce126-5111-41b5-9164-760fb9d72dd6', 'subtopic'::public.curated_course_node_type, 'Angle of twist', 'Angle of twist identifies a specific object, distinction, or relationship within torsion. Learners need to recognize and use it before combining this module''s ideas in later work. After circular shafts, angle of twist supplies what is needed to address power transmission.', 1),
  ('bfb424bc-f321-43e4-b68c-b31e27110fa0', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '670ce126-5111-41b5-9164-760fb9d72dd6', 'subtopic'::public.curated_course_node_type, 'Power transmission', 'Power transmission identifies a specific object, distinction, or relationship within torsion. Learners need to recognize and use it before combining this module''s ideas in later work. After angle of twist, power transmission supplies what is needed to address thin-walled tubes.', 2),
  ('560e49ec-a882-4e48-a7dc-22f9468f3d7c', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '670ce126-5111-41b5-9164-760fb9d72dd6', 'subtopic'::public.curated_course_node_type, 'Thin-walled tubes', 'Thin-walled tubes identifies a specific object, distinction, or relationship within torsion. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, thin-walled tubes carries the completed idea into beam shear and moment.', 3),
  ('14d3fcb9-7fa7-493b-9c68-122bd389f566', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', null, 'topic'::public.curated_course_node_type, 'Beam shear and moment', 'This module builds directly on torsion and develops beam shear and moment. It belongs here because its methods and distinctions are prerequisites for bending stress.', 4),
  ('280c7423-8452-4842-ab01-736c5e13e7f9', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '14d3fcb9-7fa7-493b-9c68-122bd389f566', 'subtopic'::public.curated_course_node_type, 'Diagrams', 'Diagrams gives beam shear and moment a reusable representation for organizing assumptions, variables, and relationships before analysis begins. It appears before load relations because that next topic assumes this starting point.', 0),
  ('7fc4e46b-5c1e-4dfc-aed4-1d51b6d53f49', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '14d3fcb9-7fa7-493b-9c68-122bd389f566', 'subtopic'::public.curated_course_node_type, 'Load relations', 'Load relations identifies a specific object, distinction, or relationship within beam shear and moment. Learners need to recognize and use it before combining this module''s ideas in later work. After diagrams, load relations supplies what is needed to address sign conventions.', 1),
  ('a0791749-905a-4b3d-9fba-bf09cc758ffe', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '14d3fcb9-7fa7-493b-9c68-122bd389f566', 'subtopic'::public.curated_course_node_type, 'Sign conventions', 'Sign conventions identifies a specific object, distinction, or relationship within beam shear and moment. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, sign conventions carries the completed idea into bending stress.', 2),
  ('b92905bf-7711-48aa-91e7-f35f5fa33e65', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', null, 'topic'::public.curated_course_node_type, 'Bending stress', 'This module builds directly on beam shear and moment and develops bending stress. It belongs here because its methods and distinctions are prerequisites for transverse shear.', 5),
  ('96f10e28-ec2d-413f-a75b-babaf0afc3e7', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', 'b92905bf-7711-48aa-91e7-f35f5fa33e65', 'subtopic'::public.curated_course_node_type, 'Flexure formula', 'Flexure formula identifies a specific object, distinction, or relationship within bending stress. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before section properties because that next topic assumes this starting point.', 0),
  ('77620795-523d-484d-88f5-101127007218', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', 'b92905bf-7711-48aa-91e7-f35f5fa33e65', 'subtopic'::public.curated_course_node_type, 'Section properties', 'Section properties identifies a specific object, distinction, or relationship within bending stress. Learners need to recognize and use it before combining this module''s ideas in later work. After flexure formula, section properties supplies what is needed to address composite and unsymmetric beams.', 1),
  ('0feba268-2f0a-402b-a9d0-a14e237b07e0', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', 'b92905bf-7711-48aa-91e7-f35f5fa33e65', 'subtopic'::public.curated_course_node_type, 'Composite and unsymmetric beams', 'Composite and unsymmetric beams identifies a specific object, distinction, or relationship within bending stress. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, composite and unsymmetric beams carries the completed idea into transverse shear.', 2),
  ('3d9d30de-8e7b-41d7-9e1f-87c4a8785315', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', null, 'topic'::public.curated_course_node_type, 'Transverse shear', 'This module builds directly on bending stress and develops transverse shear. It belongs here because its methods and distinctions are prerequisites for beam deflection.', 6),
  ('c2679b6d-7b33-4982-86a4-ffdd4f68de52', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '3d9d30de-8e7b-41d7-9e1f-87c4a8785315', 'subtopic'::public.curated_course_node_type, 'Shear formula', 'Shear formula identifies a specific object, distinction, or relationship within transverse shear. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before shear flow because that next topic assumes this starting point.', 0),
  ('e5e2531a-8193-43c6-8306-1b424bf22240', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '3d9d30de-8e7b-41d7-9e1f-87c4a8785315', 'subtopic'::public.curated_course_node_type, 'Shear flow', 'Shear flow identifies a specific object, distinction, or relationship within transverse shear. Learners need to recognize and use it before combining this module''s ideas in later work. After shear formula, shear flow supplies what is needed to address built-up sections.', 1),
  ('3c06e2a6-7b98-44e9-afb3-8b5b2b315af9', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '3d9d30de-8e7b-41d7-9e1f-87c4a8785315', 'subtopic'::public.curated_course_node_type, 'Built-up sections', 'Built-up sections identifies a specific object, distinction, or relationship within transverse shear. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, built-up sections carries the completed idea into beam deflection.', 2),
  ('47933af0-4796-4f44-a575-8480dfa72570', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', null, 'topic'::public.curated_course_node_type, 'Beam deflection', 'This module builds directly on transverse shear and develops beam deflection. It belongs here because its methods and distinctions are prerequisites for stress transformation.', 7),
  ('e1567b5d-7971-47d9-957b-f34fb1ab9d4a', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '47933af0-4796-4f44-a575-8480dfa72570', 'subtopic'::public.curated_course_node_type, 'Elastic curve', 'Elastic curve identifies a specific object, distinction, or relationship within beam deflection. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before integration because that next topic assumes this starting point.', 0),
  ('a483a0b3-645e-4a21-8b07-8a1687987b6f', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '47933af0-4796-4f44-a575-8480dfa72570', 'subtopic'::public.curated_course_node_type, 'Integration', 'Integration identifies a specific object, distinction, or relationship within beam deflection. Learners need to recognize and use it before combining this module''s ideas in later work. After elastic curve, integration supplies what is needed to address superposition.', 1),
  ('ec17c4c3-c4e1-4080-8fde-01c033d64334', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '47933af0-4796-4f44-a575-8480dfa72570', 'subtopic'::public.curated_course_node_type, 'Superposition', 'Superposition identifies a specific object, distinction, or relationship within beam deflection. Learners need to recognize and use it before combining this module''s ideas in later work. After integration, superposition supplies what is needed to address energy methods.', 2),
  ('0683a341-a6fc-4240-96cd-298d70e8a391', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '47933af0-4796-4f44-a575-8480dfa72570', 'subtopic'::public.curated_course_node_type, 'Energy methods', 'Energy methods is a governing quantity in beam deflection, linking local calculations to system-level behavior and offering a consistency check. As the final topic in this module, energy methods carries the completed idea into stress transformation.', 3),
  ('b4a08ac4-c145-47f8-b115-7352170ac23d', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', null, 'topic'::public.curated_course_node_type, 'Stress transformation', 'This module builds directly on beam deflection and develops stress transformation. It belongs here because its methods and distinctions are prerequisites for combined loading.', 8),
  ('bb6d3e4f-b6cc-4439-90a5-b7168d8d95ba', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', 'b4a08ac4-c145-47f8-b115-7352170ac23d', 'subtopic'::public.curated_course_node_type, 'Plane stress', 'Plane stress is a governing quantity in stress transformation, linking local calculations to system-level behavior and offering a consistency check. It appears before principal stress because that next topic assumes this starting point.', 0),
  ('eabf57cf-7b9f-4e66-9645-8939177bfc1b', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', 'b4a08ac4-c145-47f8-b115-7352170ac23d', 'subtopic'::public.curated_course_node_type, 'Principal stress', 'Principal stress is a governing quantity in stress transformation, linking local calculations to system-level behavior and offering a consistency check. After plane stress, principal stress supplies what is needed to address mohr’s circle.', 1);
