  ('024afd52-de33-40f1-823b-7dc15426348f', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '4ea54d39-6995-43ee-ac06-f455d9f8ff94', 'subtopic'::public.curated_course_node_type, 'Pressure vessels', 'Pressure vessels identifies a specific object, distinction, or relationship within combined loading. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before eccentric loads because that next topic assumes this starting point.', 0),
  ('60bb12e3-dab1-4861-9404-aa8e6542a3c2', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '4ea54d39-6995-43ee-ac06-f455d9f8ff94', 'subtopic'::public.curated_course_node_type, 'Eccentric loads', 'Eccentric loads identifies a specific object, distinction, or relationship within combined loading. Learners need to recognize and use it before combining this module''s ideas in later work. After pressure vessels, eccentric loads supplies what is needed to address stress concentrations.', 1),
  ('c311ac2e-2531-44ca-856a-7b6c94f028ad', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '4ea54d39-6995-43ee-ac06-f455d9f8ff94', 'subtopic'::public.curated_course_node_type, 'Stress concentrations', 'Stress concentrations is a governing quantity in combined loading, linking local calculations to system-level behavior and offering a consistency check. As the final topic in this module, stress concentrations carries the completed idea into column stability.', 2),
  ('6473d436-1e8b-4b98-8173-4c7f734d9e1c', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', null, 'topic'::public.curated_course_node_type, 'Column stability', 'This module builds directly on combined loading and develops column stability. It belongs here because its methods and distinctions are prerequisites for failure and design.', 10),
  ('9c950cdb-37d7-46d3-aa48-99355bd2b300', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '6473d436-1e8b-4b98-8173-4c7f734d9e1c', 'subtopic'::public.curated_course_node_type, 'Euler buckling', 'Euler buckling identifies a specific object, distinction, or relationship within column stability. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before effective length because that next topic assumes this starting point.', 0),
  ('5b9ad555-cc85-4153-abdb-c0c34c21c1a9', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '6473d436-1e8b-4b98-8173-4c7f734d9e1c', 'subtopic'::public.curated_course_node_type, 'Effective length', 'Effective length identifies a specific object, distinction, or relationship within column stability. Learners need to recognize and use it before combining this module''s ideas in later work. After euler buckling, effective length supplies what is needed to address inelastic limits.', 1),
  ('a771df3c-b151-4f95-af95-cd985d66e29b', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '6473d436-1e8b-4b98-8173-4c7f734d9e1c', 'subtopic'::public.curated_course_node_type, 'Inelastic limits', 'Inelastic limits makes difficult behavior in column stability tractable while exposing the assumptions and accuracy limits used by later methods. After effective length, inelastic limits supplies what is needed to address design curves.', 2),
  ('c66475d7-cb4b-4895-92b2-442d8213fbd3', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', '6473d436-1e8b-4b98-8173-4c7f734d9e1c', 'subtopic'::public.curated_course_node_type, 'Design curves', 'Design curves turns the theory of column stability into a defensible decision and exposes the relevant structure, cost, or performance trade-offs. As the final topic in this module, design curves carries the completed idea into failure and design.', 3),
  ('fd2f8f7f-b28a-4996-81e4-672bb33153b3', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', null, 'topic'::public.curated_course_node_type, 'Failure and design', 'This culminating module draws on column stability and develops failure and design. It belongs last because it requires the earlier tools to be selected, combined, and evaluated rather than used one at a time.', 11),
  ('61088bf0-69db-429c-8496-70f5b96c0953', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', 'fd2f8f7f-b28a-4996-81e4-672bb33153b3', 'subtopic'::public.curated_course_node_type, 'Yield criteria', 'Yield criteria identifies a specific object, distinction, or relationship within failure and design. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before fatigue basics because that next topic assumes this starting point.', 0),
  ('f134d48d-8f61-472b-abb4-4e9502f19dfb', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', 'fd2f8f7f-b28a-4996-81e4-672bb33153b3', 'subtopic'::public.curated_course_node_type, 'Fatigue basics', 'Fatigue basics identifies a specific object, distinction, or relationship within failure and design. Learners need to recognize and use it before combining this module''s ideas in later work. After yield criteria, fatigue basics supplies what is needed to address factor of safety.', 1),
  ('b4aee9be-4845-4c3f-90e5-3cf9c6045e96', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', 'fd2f8f7f-b28a-4996-81e4-672bb33153b3', 'subtopic'::public.curated_course_node_type, 'Factor of safety', 'Factor of safety explains how failure and design behaves under misuse, faults, or constraints, which is essential for responsible real-world application. After fatigue basics, factor of safety supplies what is needed to address design synthesis.', 2),
  ('f88e8045-98aa-4a98-870b-29ddf8596d00', '627739e7-79a9-43a8-b2b8-99e5ef8f89ac', 'fd2f8f7f-b28a-4996-81e4-672bb33153b3', 'subtopic'::public.curated_course_node_type, 'Design synthesis', 'Design synthesis turns the theory of failure and design into a defensible decision and exposes the relevant structure, cost, or performance trade-offs. As the final course topic, design synthesis requires ideas from the complete path to be integrated and transferred.', 3);
